class DogListScreen extends StatefulWidget {
  const DogListScreen({super.key});

  @override
  State<DogListScreen> createState() => _DogListScreenState();
}

class _DogListScreenState extends State<DogListScreen> {
  late Future<List<Dog>> _dogsFuture;

  @override
  void initState() {
    super.initState();
    _refreshDogList();
  }

  void _refreshDogList() {
    setState(() {
      _dogsFuture = DatabaseHelper().getDogs();
    });
  }

  void _addDog() async {
    // In a real app, you'd get this data from a form.
    final newDog = Dog(id: DateTime.now().millisecondsSinceEpoch, name: 'Fido', age: 3);
    await DatabaseHelper().insertDog(newDog);
    _refreshDogList();
  }

  @override
  Widget build(BuildContext context) {
    return Scaffold(
      appBar: AppBar(title: const Text('My Dogs')),
      body: FutureBuilder<List<Dog>>(
        future: _dogsFuture,
        builder: (context, snapshot) {
          if (snapshot.connectionState == ConnectionState.waiting) {
            return const Center(child: CircularProgressIndicator());
          } else if (snapshot.hasError) {
            return Center(child: Text('Error: ${snapshot.error}'));
          } else if (!snapshot.hasData || snapshot.data!.isEmpty) {
            return const Center(child: Text('No dogs found.'));
          } else {
            final dogs = snapshot.data!;
            return ListView.builder(
              itemCount: dogs.length,
              itemBuilder: (context, index) {
                final dog = dogs[index];
                return ListTile(
                  title: Text(dog.name),
                  subtitle: Text('Age: ${dog.age}'),
                  trailing: IconButton(
                    icon: const Icon(Icons.delete),
                    onPressed: () async {
                      await DatabaseHelper().deleteDog(dog.id);
                      _refreshDogList();
                    },
                  ),
                );
              },
            );
          }
        },
      ),
      floatingActionButton: FloatingActionButton(
        onPressed: _addDog,
        child: const Icon(Icons.add),
      ),
    );
  }
}
